    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Apartamentos próximos ao campus indicados pelo UC San Diego Division of Extended Studies para estudantes internacionais, operados por fornecedores parceiros (como a AC Housing/Anatolia). São unidades mobiliadas, com quarto individual ou compartilhado, cozinha para self-catering, limpeza quinzenal e acesso a piscina e academia no condomínio, a curta distância do campus e das aulas. Os pacotes são normalmente fechados em blocos de semanas (por exemplo, 9, 11 ou 26 semanas), o que favorece quem faz programas mais longos. A equipe de Health and Welfare da universidade auxilia os alunos com dúvidas sobre moradia, saúde, bem-estar e transporte, mas não faz a reserva nem processa pagamentos: a contratação e os valores são tratados diretamente com o fornecedor, que não é afiliado à universidade. Nesta opção o quarto é duplo/twin (para quem viaja acompanhado ou dividido com outro estudante do mesmo gênero) e o banheiro é compartilhado. As refeições não estão inclusas: o regime é self-catering, com liberdade para cozinhar e montar a própria rotina alimentar. Estadia mínima de 4 semanas.</p><p>Pagina oficial de Housing da UC San Diego Division of Extended Studies (preços 2026). Apartments by Anatolia, proximos ao campus, mobiliados e sem refeições. Os pacotes sao fechados por duração: 4 semanas, 9 semanas (1 semana de orientacao presencial mais 8 de aulas), 11 semanas e 26 semanas. Esta linha e o pacote de 4 semanas: quarto compartilhado US$1.360 (US$340 por semana) e quarto privativo US$2.380 (US$595 por semana). Pre-pagamento não reembolsável de US$250 a titulo de taxa de colocação, que não abate o aluguel. Traslado do aeroporto US$95. Não ha suplemento de alta temporada, desconto de baixa temporada, dieta especial, noite extra nem caução publicados.</p>','["Mobiliado", "Perto da Escola", "Piscina", "Academia", "Limpeza Quinzenal", "Cozinha para Self-catering", "Pacotes de 9, 11 ou 26 Semanas", "Apoio da Equipe de Health and Welfare", "Contrato Direto com o Fornecedor", "Quarto Duplo/Twin", "Banheiro Compartilhado", "Self-catering", "Ideal para quem faz programas longos e quer previsibilidade de custo", "Ideal para quem quer cozinhar e ter autonomia", "Ideal para quem valoriza piscina e academia no condomínio", "Ideal para quem quer morar perto do campus em La Jolla", "Ideal para quem viaja acompanhado ou quer dividir custos", "Ideal para quem gosta de socializar e não se importa em dividir espaços", "Ideal para quem quer autonomia para cozinhar e controlar o orçamento"]'::jsonb,'["Menos indicado para quem fica poucas semanas", "Menos indicado para quem quer refeições inclusas", "Menos indicado para quem espera que a universidade faça a reserva e a gestão do contrato", "Menos indicado para quem prefere imersão cultural com uma família americana", "Menos indicado para quem precisa de privacidade e silêncio", "Menos indicado para quem faz questão de banheiro exclusivo", "Menos indicado para quem não quer cozinhar nem se preocupar com compras de supermercado"]'::jsonb);
