    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Apartamentos próximos ao campus indicados pelo UC San Diego Division of Extended Studies para estudantes internacionais, operados por fornecedores parceiros (como a AC Housing/Anatolia). São unidades mobiliadas, com quarto individual ou compartilhado, cozinha para self-catering, limpeza quinzenal e acesso a piscina e academia no condomínio, a curta distância do campus e das aulas. Os pacotes são normalmente fechados em blocos de semanas (por exemplo, 9, 11 ou 26 semanas), o que favorece quem faz programas mais longos. A equipe de Health and Welfare da universidade auxilia os alunos com dúvidas sobre moradia, saúde, bem-estar e transporte, mas não faz a reserva nem processa pagamentos: a contratação e os valores são tratados diretamente com o fornecedor, que não é afiliado à universidade. Nesta opção você fica em quarto individual com banheiro privativo, de uso exclusivo. As refeições não estão inclusas: o regime é self-catering, com liberdade para cozinhar e montar a própria rotina alimentar. Pacote operado pela Anatolia (AC Housing), com preço fechado para o bloco de semanas indicado. Estadia mínima de 11 semanas.</p><p>Pagina oficial de Housing da UC San Diego Division of Extended Studies (preços 2026). Apartments by Anatolia, proximos ao campus (15 minutos de ônibus ou bicicleta), mobiliados, com piscina, academia, limpeza quinzenal, roupa de cama, utensilios de cozinha, TV a cabo, wi-fi, telefone local e cota de utilidades. Sem refeições: cozinha completa para preparo próprio. Quarto compartilhado significa dois alunos por quarto e quatro por apartamento, com dois banheiros; quarto privativo tem banheiro próprio e área comum e cozinha divididas com outros dois alunos. Apartamentos por genero; casais mediante solicitacao. Pre-pagamento não reembolsável de US$250 a titulo de taxa de colocação, que não abate o aluguel. Traslado do aeroporto de San Diego US$95. Os pacotes sao fechados por duração (4, 9, 11 e 26 semanas). Sem suplemento de temporada, dieta especial, noite extra ou caução publicados. Esta linha: pacote de 11 semanas, quarto privativo, US$7,250 no total, equivalente a US$659.09 por semana.</p>','["Mobiliado", "Perto da Escola", "Piscina", "Academia", "Limpeza Quinzenal", "Cozinha para Self-catering", "Pacotes de 9, 11 ou 26 Semanas", "Apoio da Equipe de Health and Welfare", "Contrato Direto com o Fornecedor", "Quarto Individual", "Banheiro Privativo", "Self-catering", "Operado pela Anatolia (AC Housing)", "Ideal para quem faz programas longos e quer previsibilidade de custo", "Ideal para quem quer cozinhar e ter autonomia", "Ideal para quem valoriza piscina e academia no condomínio", "Ideal para quem quer morar perto do campus em La Jolla", "Ideal para quem valoriza privacidade total e silêncio para estudar", "Ideal para quem prefere não dividir banheiro com ninguém", "Ideal para quem quer autonomia para cozinhar e controlar o orçamento"]'::jsonb,'["Menos indicado para quem fica poucas semanas", "Menos indicado para quem quer refeições inclusas", "Menos indicado para quem espera que a universidade faça a reserva e a gestão do contrato", "Menos indicado para quem prefere imersão cultural com uma família americana", "Menos indicado para quem procura a alternativa mais barata", "Menos indicado para quem quer dividir o quarto com um amigo para reduzir custos", "Menos indicado para quem não quer cozinhar nem se preocupar com compras de supermercado"]'::jsonb);
    insert into price_template (tenant_id, campus_id, name, price_basis, duration_type, unit, currency, charge_in_tiers, valid_from, status) values (v_tid,'2f765e72-3f81-5dea-bcd3-9f1330de0835','Apartamento — quarto individual, banheiro privativo, sem refeições','duration','flexible','week','USD',false,'2026-01-01','active') returning id into v_tpl;
    insert into price_tier (price_template_id, min_quantity, unit_price, sort) values (v_tpl,11,659.09,0);
    insert into price_template_product (price_template_id, product_id) values (v_tpl, v_pid);
    insert into fee (tenant_id, campus_id, name, fee_type, charge_basis, amount, currency, is_mandatory, is_refundable) values (v_tid,'2f765e72-3f81-5dea-bcd3-9f1330de0835','Taxa de colocação em acomodação','placement','once_per_item',250.0,'USD',true,false) returning id into v_fee;
    insert into fee_product (fee_id, product_id) values (v_fee, v_pid);
